document.addEventListener("DOMContentLoaded",function(){document.documentElement.classList.add("js-enabled");var processSteps=document.querySelectorAll(".process-step");if(processSteps.length){var observer=new IntersectionObserver(function(entries,obs){entries.forEach(function(entry){if(entry.isIntersecting){entry.target.classList.add("is-revealed");obs.unobserve(entry.target);}});},{threshold:0.2,rootMargin:"0px 0px -50px 0px"});processSteps.forEach(function(step){observer.observe(step);});}var fadeUpCards=document.querySelectorAll(".enterprise-solutions-section .fade-up");if(fadeUpCards.length){var fadeObserver=new IntersectionObserver(function(entries,obs){entries.forEach(function(entry){if(entry.isIntersecting){fadeUpCards.forEach(function(card,index){setTimeout(function(){card.classList.add("active");},index*180);});obs.disconnect();}});},{threshold:0.12,rootMargin:"0px 0px -40px 0px"});var section=document.querySelector(".enterprise-solutions-section");if(section)fadeObserver.observe(section);}var animatedElements=document.querySelectorAll(".scroll-fade-up");var scrollObserver=new IntersectionObserver(function(entries,obs){entries.forEach(function(entry){if(entry.isIntersecting){entry.target.classList.add("is-visible");obs.unobserve(entry.target);}});},{threshold:0.15,rootMargin:"0px 0px -50px 0px"});animatedElements.forEach(function(el){scrollObserver.observe(el);});var fadeElems=document.querySelectorAll(".fade-in-section");fadeElems.forEach(function(el){scrollObserver.observe(el);});var popup=document.getElementById("founder-popup");var closeBtn=document.getElementById("close-founder-popup");if(popup&&!sessionStorage.getItem("founder_popup_closed")){setTimeout(function(){popup.classList.add("show");},120000);}if(closeBtn){closeBtn.addEventListener("click",function(){popup.classList.remove("show");sessionStorage.setItem("founder_popup_closed","true");});}});